    const { BayesianUpdate, DenominatorNeglect, TimeSeries } = initFPTBattery.tasks;

    // ── BayesianUpdate subclass ───────────────────────────────────────────────
    class TrimmedBayesianUpdate extends BayesianUpdate {
        constructor(name, media_basepath, jsPsych, custom_task_settings) {
            const dropSpecs = custom_task_settings.drop_unique_trials_with_ball_splits || [];
            const { drop_unique_trials_with_ball_splits, ...clean_settings } = custom_task_settings;
            super(name, media_basepath, jsPsych, clean_settings);
            if (dropSpecs.length &gt; 0) {
                this._drop_unique_trials(dropSpecs);
            }
            this._log_ball_split_distribution();
        }

        _log_ball_split_distribution() {
            const seenUnique = new Set();
            const countsBySplit = {};
            for (const blockKey of Object.keys(this.task_data.test_trials)) {
                for (const trialKey of Object.keys(this.task_data.test_trials[blockKey])) {
                    const t = this.task_data.test_trials[blockKey][trialKey];
                    if (seenUnique.has(t.unique_trial)) continue;
                    seenUnique.add(t.unique_trial);
                    const key = `[${t.ball_split[0]}, ${t.ball_split[1]}]`;
                    countsBySplit[key] = (countsBySplit[key] || 0) + 1;
                }
            }
            console.log(
                `%c[BayesianUpdate] final test-trial ball_split distribution (unique trials):`,
                'font-weight: bold; color: #0a7; font-size: 13px;',
                countsBySplit,
                `(total unique = ${seenUnique.size}, total draws = ${this.settings.test_trials_n})`
            );
        }

        _drop_unique_trials(dropSpecs) {
            const blockKeys = Object.keys(this.task_data.test_trials).sort();

            const dropUniqueTrialIndices = new Set();
            for (const drop of dropSpecs) {
                let matched = false;
                for (const blockKey of blockKeys) {
                    for (const trialKey of Object.keys(this.task_data.test_trials[blockKey])) {
                        const t = this.task_data.test_trials[blockKey][trialKey];
                        if (dropUniqueTrialIndices.has(t.unique_trial)) continue;
                        if (t.ball_split[0] === drop[0] && t.ball_split[1] === drop[1]) {
                            dropUniqueTrialIndices.add(t.unique_trial);
                            matched = true;
                            break;
                        }
                    }
                    if (matched) break;
                }
                if (!matched) {
                    console.warn(
                        `[TrimmedBayesianUpdate] No unmatched unique trial with ball_split [${drop}] found to drop.`
                    );
                }
            }

            for (const blockKey of blockKeys) {
                for (const trialKey of Object.keys(this.task_data.test_trials[blockKey])) {
                    if (dropUniqueTrialIndices.has(this.task_data.test_trials[blockKey][trialKey].unique_trial)) {
                        delete this.task_data.test_trials[blockKey][trialKey];
                    }
                }
            }

            let newTrialInd = 0;
            const oldToNewUnique = new Map();
            let nextNewUnique = 0;
            for (const blockKey of blockKeys) {
                for (const trialKey of Object.keys(this.task_data.test_trials[blockKey])) {
                    const t = this.task_data.test_trials[blockKey][trialKey];
                    t.trial = newTrialInd++;
                    if (!oldToNewUnique.has(t.unique_trial)) {
                        oldToNewUnique.set(t.unique_trial, nextNewUnique++);
                    }
                    t.unique_trial = oldToNewUnique.get(t.unique_trial);
                }
            }
            this.settings.test_trials_n = newTrialInd;
            this.settings.unique_test_trials_n = newTrialInd / this.settings.draws_per_unique_trial;
            const n = this.settings.unique_test_trials_n;
            const setsWord = n === 1 ? 'set' : 'sets';
            this.test_trials_instructions = {
                ...this.test_trials_instructions,
                pages: () =&gt; {
                    if (this.settings.task_version === 'easy') {
                        return [
                            `&lt;p class="instructions-title" style="text-align: center"&gt;The box and balls task - Predicting the Next Box&lt;/p&gt;
                            &lt;p&gt;We will now progress to the test decisions. The task will be broken into ${n} ${setsWord} of ${this.settings.draws_per_unique_trial} decisions. After every set of ${this.settings.draws_per_unique_trial} decisions, the task will reset and you will start from the beginning, with no information about which of the two boxes is the one in the middle.&lt;/p&gt;
                            &lt;p&gt;Remember that:&lt;/p&gt;
                            &lt;ul&gt;
                                &lt;li&gt;the randomly selected box (represented by the one that has black balls) is one of the two boxes (majority red or majority blue boxes)&lt;/li&gt;
                                &lt;li&gt;your task is to decide how likely it is that the randomly selected box is the one with majority blue balls or the one with majority red balls&lt;/li&gt;
                                &lt;li&gt;after every draw, the drawn ball is put back into the black box and a new draw occurs; for every draw, the same 100 balls are used&lt;/li&gt;
                            &lt;/ul&gt;
                            &lt;p&gt;Continue to the test decisions whenever you are ready.&lt;/p&gt;`,
                        ];
                    } else {
                        return [
                            `&lt;p class="instructions-title" style="text-align: center"&gt;The box and balls task - Predicting the Next Ball&lt;/p&gt;
                            &lt;p&gt;We will now progress to the test decisions. The task will be broken into ${n} ${setsWord} of ${this.settings.draws_per_unique_trial} decisions. After every set of ${this.settings.draws_per_unique_trial} decisions, the task will reset and you will start from the beginning, with no information about which of the two boxes is the one in the middle.&lt;/p&gt;
                            &lt;p&gt;Remember that:&lt;/p&gt;
                            &lt;ul&gt;
                                &lt;li&gt;the randomly selected box (represented by the one that has black balls) is one of the two boxes (majority red or majority blue boxes)&lt;/li&gt;
                                &lt;li&gt;your task is to predict the probability that the next ball drawn will be blue&lt;/li&gt;
                                &lt;li&gt;after every draw, the drawn ball is put back into the black box and a new draw occurs; for every draw, the same 100 balls are used&lt;/li&gt;
                            &lt;/ul&gt;
                            &lt;p&gt;Continue to the test decisions whenever you are ready.&lt;/p&gt;`,
                        ];
                    }
                },
            };
        }
    }

    // ── DenominatorNeglect subclass ───────────────────────────────────────────
    class FilteredDenominatorNeglect extends DenominatorNeglect {
        constructor(name, media_basepath, jsPsych, custom_task_settings) {
            const keepSpecs = custom_task_settings.keep_only_trials || null;
            const { keep_only_trials, ...clean_settings } = custom_task_settings;
            super(name, media_basepath, jsPsych, clean_settings);
            if (keepSpecs && keepSpecs.length &gt; 0) {
                this._keep_only_trials(keepSpecs);
            }
        }

        _keep_only_trials(keepSpecs) {
            const blockKeys = Object.keys(this.task_data.test_trials).sort();

            const keepKeys = new Set(
                keepSpecs.map(([choice_type, small_prop, diff]) =&gt;
                    `${choice_type}|${small_prop.toFixed(4)}|${diff.toFixed(4)}`
                )
            );

            for (const blockKey of blockKeys) {
                for (const trialKey of Object.keys(this.task_data.test_trials[blockKey])) {
                    const t = this.task_data.test_trials[blockKey][trialKey];

                    const small_prop = t.left_lottery_type === 'small'
                        ? t.left_lottery_gold_prop
                        : t.right_lottery_gold_prop;
                    const large_prop = t.left_lottery_type === 'large'
                        ? t.left_lottery_gold_prop
                        : t.right_lottery_gold_prop;

                    const diff = t.choice_type === 'harmony'
                        ? (large_prop - small_prop).toFixed(4)
                        : (small_prop - large_prop).toFixed(4);

                    const key = `${t.choice_type}|${small_prop.toFixed(4)}|${diff}`;
                    if (!keepKeys.has(key)) {
                        delete this.task_data.test_trials[blockKey][trialKey];
                    }
                }
            }

            let newTrialInd = 0;
            for (const blockKey of blockKeys) {
                for (const trialKey of Object.keys(this.task_data.test_trials[blockKey])) {
                    this.task_data.test_trials[blockKey][trialKey].trial = newTrialInd++;
                }
            }
            this.settings.test_trials_n = newTrialInd;

            console.log(
                `%c[FilteredDenominatorNeglect] kept ${newTrialInd} test trials`,
                'font-weight: bold; color: #0a7; font-size: 13px;'
            );
        }
    }

    // ── TimeSeries subclass ───────────────────────────────────────────
    class FilteredTimeSeries extends TimeSeries {
