                    `,
                ],
            };
        }
    }

    // ── Shuffle utility for task-level randomization ─────────────────────────
    function shuffle(arr) {
        const a = [...arr];
        for (let i = a.length - 1; i &gt; 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [a[i], a[j]] = [a[j], a[i]];
        }
        return a;
    }

